import assert from 'node:assert/strict';import fs from 'node:fs';import {JSDOM} from 'jsdom';
const w=new JSDOM('<body><main id="travel-root"><h4>Traveling</h4><section aria-label="Flight progress">Torn to Japan. Remaining Flight Time - 00:00:05</section></main></body>',{url:'https://www.torn.com/page.php?sid=travel',runScripts:'outside-only',pretendToBeVisual:true}).window,d=w.document;d.hasFocus=()=>true;w.HTMLElement.prototype.getClientRects=function(){return this.hidden?[]:[{}];};w.HTMLElement.prototype.scrollIntoView=()=>{};w.HTMLElement.prototype.setPointerCapture=()=>{};w.alert=()=>{};w.fetch=async()=>{throw Error('Unexpected fetch');};const requests=[],events=[],errors=[];d.addEventListener('tu-snatch-run-diagnostic',e=>events.push(JSON.parse(e.detail)));w.addEventListener('error',e=>{errors.push(e.error);e.preventDefault();});w.GM_xmlhttpRequest=o=>{requests.push({method:o.method||'GET',url:o.url});const data=o.url.endsWith('/api/auth/agreement')?{accepted:true,agreement:{agreement_version:'fixture-v1',agreement_number:1,agreement_date:'2026-11-07'}}:o.url.endsWith('/health')?{tu_monitor:1}:o.url.includes('/api/monitor/')?{ok:true}:{info:{access:{type:'Public Only'},user:{id:42}}};queueMicrotask(()=>o.onload?.({status:200,responseText:JSON.stringify(data)}));};
w.localStorage.setItem('tu:identity:public-only-key:v1','abcdef0123456789');w.localStorage.setItem('tu:agreement:accepted','fixture-v1');w.sessionStorage.setItem('tu:dev:auth:session:v1','fixture-session');w.localStorage.setItem('tu-item-monitor-v1',JSON.stringify([{key:'id:206',name:'Xanax',category:'Foreign',minQty:1}]));w.sessionStorage.setItem('tu:snatch-run:v1',JSON.stringify({ownerId:'42',country:'jap',intentId:'synthetic-landing',watchKey:'id:206',watchName:'Xanax',minimumQty:1,planHospitalize:true,hospital:true,hospitalization:{id:3,name:'Synthetic hospital item'},hospitalizations:[{id:3,name:'Synthetic hospital item'}],stage:'hospitalize',stockAt:0,hospitalizationAttempted:false,hospitalizedConfirmed:false}));
const pause=()=>new Promise(r=>setTimeout(r,80));try{w.eval(fs.readFileSync(new URL('../dist/tu-integrated-staging-dev.user.js',import.meta.url),'utf8'));await pause();d.querySelector('[data-tab=modules]').click();const card=name=>[...d.querySelectorAll('.tu-card')].find(c=>c.querySelector('strong')?.textContent===name).querySelector('button').click();card('Business Tools');card('Travel Assistant and Item Monitor');await pause();const button=d.getElementById('tu-snatch-run');assert.equal(button.dataset.snatchStage,'hospitalize');const root=d.getElementById('travel-root');root.innerHTML='<h4>Japan</h4><ul class="inventoryPanel_fixture" aria-label="Inventory 0 items"><li class="inventorySlot_fixture">Empty slot</li></ul><div class="stockTableWrapper_fixture"><div class="itemsHeader_fixture"><span>Name</span><span>Stock</span><span>Cost</span></div><ul><li><div class="row_fixture" data-item-id="206"><span class="tabletColB_fixture">Xanax</span><span class="tabletColC_fixture">0</span><span class="tabletColD_fixture">$100</span><button>Buy</button></div></li></ul></div>';const hospital=d.createElement('a');hospital.setAttribute('aria-label','Hospital: Temporary status');d.body.prepend(hospital);w.dispatchEvent(new w.Event('focus'));assert.equal(button.dataset.snatchStage,'waiting');hospital.remove();w.dispatchEvent(new w.Event('focus'));assert.equal(button.dataset.snatchStage,'hospitalize');assert.equal(button.getAttribute('aria-disabled'),'false');assert.ok(events.some(e=>e.event==='hospitalize-restored'));assert.ok(!events.some(e=>e.event==='action-start'),'Restoring readiness sends no gameplay action');assert.ok(!requests.some(r=>r.method==='POST'&&!r.url.includes('/api/monitor/')),'No gameplay POST');assert.deepEqual(errors,[]);}finally{w.TornUtilities?.closeActiveModule();w.close();}
